using Godot;
using System;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
public partial class ImageWorkspaceOperations
{
    private static void CloseWithDialog(ConfirmationDialog dialog){dialog.Confirmed+=dialog.QueueFree;dialog.Canceled+=dialog.QueueFree;dialog.CloseRequested+=dialog.QueueFree;}
    public void canvas_size_dialog(Control owner)
    {
        var dialog=new ConfirmationDialog{Title="Canvas size"};owner.AddChild(dialog);var row=new HBoxContainer();dialog.AddChild(row);var size=Document(owner).Get("canvas_size").AsVector2I();var width=new SpinBox{MinValue=1,MaxValue=8192,Value=size.X};row.AddChild(width);var height=new SpinBox{MinValue=1,MaxValue=8192,Value=size.Y};row.AddChild(height);dialog.Confirmed+=()=>{Action(owner,()=>Document(owner).Set("canvas_size",new Vector2I((int)width.Value,(int)height.Value)));_canvas.clear_selection(Canvas(owner));_canvas.fit(Canvas(owner));};CloseWithDialog(dialog);dialog.PopupCentered(new Vector2I(350,120));
    }
    public void image_size_dialog(Control owner)
    {
        var dialog=new ConfirmationDialog{Title="Resize image"};owner.AddChild(dialog);var column=new VBoxContainer{CustomMinimumSize=new Vector2(390,190)};column.AddThemeConstantOverride("separation",10);dialog.AddChild(column);var intro=new Label{Text="Scale the canvas and every layer together"};intro.AddThemeColorOverride("font_color",new Color("8fa8bb"));column.AddChild(intro);var row=new HBoxContainer();column.AddChild(row);var size=Document(owner).Get("canvas_size").AsVector2I();var width=new SpinBox{MinValue=1,MaxValue=16384,Value=size.X,Prefix="Width  ",SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};row.AddChild(width);var height=new SpinBox{MinValue=1,MaxValue=16384,Value=size.Y,Prefix="Height  ",SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};row.AddChild(height);var linked=new CheckButton{Text="Keep image aspect ratio",ButtonPressed=true};column.AddChild(linked);double ratio=(double)size.X/Math.Max(1,size.Y);bool syncing=false;width.ValueChanged+=value=>{if(linked.ButtonPressed&&!syncing){syncing=true;height.Value=Mathf.Round(value/ratio);syncing=false;}};height.ValueChanged+=value=>{if(linked.ButtonPressed&&!syncing){syncing=true;width.Value=Mathf.Round(value*ratio);syncing=false;}};var quality=new OptionButton();foreach(string caption in new[]{"Lanczos · best for photos","Bilinear · fast and smooth","Nearest · pixel art"})quality.AddItem(caption);column.AddChild(quality);dialog.Confirmed+=()=>scale_image(owner,new Vector2I((int)width.Value,(int)height.Value),quality.Selected==0?(int)Image.Interpolation.Lanczos:quality.Selected==1?(int)Image.Interpolation.Bilinear:(int)Image.Interpolation.Nearest);CloseWithDialog(dialog);dialog.PopupCentered(new Vector2I(440,250));
    }
    private static Texture2D ResizeTexture(Texture2D texture,Vector2 ratio,Image.Interpolation interpolation){using var source=texture.GetImage();using var bitmap=(Image)source.Duplicate();bitmap.Resize(Math.Max(1,Mathf.RoundToInt(bitmap.GetWidth()*ratio.X)),Math.Max(1,Mathf.RoundToInt(bitmap.GetHeight()*ratio.Y)),interpolation);return ImageTexture.CreateFromImage(bitmap);}
    public void scale_image(Control owner,Vector2I size,int interpolation)
    {
        var document=Document(owner);var current=document.Get("canvas_size").AsVector2I();if(size.X<1||size.Y<1||size==current)return;var ratio=(Vector2)size/(Vector2)current;Action(owner,()=>{foreach(var value in document.Get("layers").AsGodotArray()){var layer=value.As<Resource>();layer.Set("position",layer.Get("position").AsVector2()*ratio);layer.Set("dimensions",layer.Get("dimensions").AsVector2()*ratio);string kind=layer.Get("kind").AsString();if(layer.Get("texture").As<Texture2D>() is Texture2D texture&&(kind is "image" or "paint" or "basic")){layer.Set("texture",ResizeTexture(texture,ratio,(Image.Interpolation)interpolation));if(layer.Get("paint_base").As<Texture2D>() is Texture2D original)layer.Set("paint_base",ResizeTexture(original,ratio,(Image.Interpolation)interpolation));}if(layer.Get("mask").As<Texture2D>() is Texture2D mask)layer.Set("mask",ResizeTexture(mask,ratio,Image.Interpolation.Bilinear));if(kind=="text"){var properties=layer.Get("properties").AsGodotDictionary();properties["text_scale"]=Get(properties,"text_scale",1.0).AsDouble()*Math.Min(ratio.X,ratio.Y);}}document.Set("canvas_size",size);});_canvas.clear_selection(Canvas(owner));_canvas.fit(Canvas(owner));owner.Get("status").As<Label>().Text="Image resized to "+size.X+" × "+size.Y;
    }
    public void replace_image_result(Control owner,Resource layer,string chosen)
    {
        if(chosen=="::empty-resource::"){Action(owner,()=>{layer.Get("live_paint").AsGodotArray().Clear();layer.Set("texture",default(Variant));layer.Set("paint_base",default(Variant));var properties=layer.Get("properties").AsGodotDictionary();properties.Remove("noise_image");properties.Remove("image_path");});return;}if(chosen.Length==0)return;using var bitmap=Image.LoadFromFile(chosen);if(bitmap!=null)Action(owner,()=>{layer.Get("live_paint").AsGodotArray().Clear();var texture=ImageTexture.CreateFromImage(bitmap);layer.Set("texture",texture);layer.Set("paint_base",texture);var properties=layer.Get("properties").AsGodotDictionary();properties.Remove("noise_image");properties["image_path"]=chosen;});
    }
    public void import_paths(Control owner,string[] paths,Vector2 at)
    {
        var document=Document(owner);var size=document.Get("canvas_size").AsVector2I();var extensions=new HashSet<string>{"png","jpg","jpeg","webp","bmp","tga","svg","hdr","exr"};var layers=new List<Resource>();foreach(string file in paths){if(!extensions.Contains(file.GetExtension().ToLowerInvariant()))continue;using var bitmap=Image.LoadFromFile(file);if(bitmap==null||bitmap.IsEmpty())continue;var layer=_layers.create("image",size);layer.Set("label",file.GetFile().GetBaseName());var texture=ImageTexture.CreateFromImage(bitmap);layer.Set("texture",texture);layer.Set("paint_base",texture);float fit=Math.Min(1,Math.Min((float)size.X/bitmap.GetWidth(),(float)size.Y/bitmap.GetHeight()));var dimensions=(Vector2)bitmap.GetSize()*fit;layer.Set("dimensions",dimensions);layer.Set("position",at-dimensions*.5f);layers.Add(layer);owner.Call("_remember_asset",file);}if(layers.Count==0)return;Action(owner,()=>{var selected=Canvas(owner).Get("selected").AsGodotArray();selected.Clear();foreach(var layer in layers){document.Get("layers").AsGodotArray().Add(layer);selected.Add(layer.Get("id"));}});owner.Call("_set_tool","move");
    }
}
